#include <stdio.h>
#include <string.h>
#include <thinkthen.h>

thinkthen_engine *tt = thinkthen_engine_new();

/* one filled form per report: export, login, and billing */
const char *annotate = "{\"annotate\": {\"version\": 1, \"questions\": {"
    "\"steps\": {\"decide\": \"Does the report give steps to reproduce?\"}, "
    "\"area\": {\"choose\": \"Which part of the app is this?\", "
    "\"options\": [\"export\", \"login\", \"billing\"]}}}, "
    "\"records\": [\"CSV export fails. Steps: click Export.\", "
    "\"The login page spins and nobody can sign in.\", "
    "\"The Pay button on the billing page is too blue.\"]}";
char *forms = thinkthen_call(tt, annotate);
puts(forms ? forms : thinkthen_error_message(tt));
thinkthen_free_string(forms);
